-- A108 — perfil de construtora e associação estrutural em rascunho. Sem dados fiscais, contato, documento, correspondente, unidades, estoque, preço, contrato ou financeiro.
create type public.urban_developer_relationship_kind as enum ('development_responsible', 'commercial_reference', 'other');
alter table public.urban_developments add constraint urban_developments_tenant_match unique (id, organization_id);
create table public.urban_developer_profiles (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete restrict, party_id uuid not null references public.party_records(id) on delete restrict, state public.party_lifecycle_state not null default 'draft', created_by uuid not null references public.identity_subjects(user_id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint urban_developer_profiles_tenant_unique unique (organization_id, party_id), constraint urban_developer_profiles_tenant_match unique (id, organization_id));
create table public.urban_development_developer_links (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete restrict, development_id uuid not null, developer_profile_id uuid not null, relationship public.urban_developer_relationship_kind not null default 'development_responsible', state public.party_lifecycle_state not null default 'draft', created_by uuid not null references public.identity_subjects(user_id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint urban_development_developer_links_development_fk foreign key (development_id, organization_id) references public.urban_developments(id, organization_id) on delete restrict, constraint urban_development_developer_links_profile_fk foreign key (developer_profile_id, organization_id) references public.urban_developer_profiles(id, organization_id) on delete restrict, constraint urban_development_developer_links_unique unique (organization_id, development_id, developer_profile_id));
create index urban_developer_profiles_context_lookup on public.urban_developer_profiles (organization_id, state, created_at desc); create index urban_development_developer_links_context_lookup on public.urban_development_developer_links (organization_id, state, created_at desc);
alter table public.urban_developer_profiles enable row level security; alter table public.urban_development_developer_links enable row level security; revoke all on table public.urban_developer_profiles from public, anon, authenticated; revoke all on table public.urban_development_developer_links from public, anon, authenticated;
create policy urban_developer_profiles_deny_direct_access on public.urban_developer_profiles as restrictive for all to public using (false) with check (false); create policy urban_development_developer_links_deny_direct_access on public.urban_development_developer_links as restrictive for all to public using (false) with check (false);
create or replace function public.urban_register_draft_developer(p_actor_user_id uuid, p_organization_id uuid, p_module public.operating_module, p_purpose_code text, p_party_id uuid, p_correlation_id uuid) returns uuid language plpgsql security definer set search_path = '' as $$ declare v_existing_target uuid; v_profile_id uuid; begin perform private.require_urban_pipeline_authority(p_actor_user_id, p_organization_id, p_module, p_purpose_code); select target_id into v_existing_target from public.admin_audit_events where command_name = 'urban_register_draft_developer' and correlation_id = p_correlation_id and outcome = 'allowed' order by occurred_at desc limit 1; if v_existing_target is not null then return v_existing_target; end if; if not exists (select 1 from public.party_records p where p.id = p_party_id and p.organization_id = p_organization_id and p.kind = 'legal_entity' and p.state = 'draft') then raise exception using errcode = '42501', message = 'URBAN_DEVELOPER_PARTY_DENIED'; end if; select id into v_profile_id from public.urban_developer_profiles where organization_id = p_organization_id and party_id = p_party_id and state = 'draft'; if v_profile_id is null then insert into public.urban_developer_profiles (organization_id, party_id, state, created_by) values (p_organization_id, p_party_id, 'draft', p_actor_user_id) returning id into v_profile_id; end if; insert into public.admin_audit_events (correlation_id, actor_user_id, organization_id, command_name, outcome, target_type, target_id, payload_redacted) values (p_correlation_id, p_actor_user_id, p_organization_id, 'urban_register_draft_developer', 'allowed', 'urban_developer_profile', v_profile_id, jsonb_build_object('module', p_module::text, 'purpose_code', trim(p_purpose_code), 'party_reference_present', true)); return v_profile_id; end; $$;
create or replace function public.urban_list_draft_developers(p_actor_user_id uuid, p_organization_id uuid, p_module public.operating_module, p_purpose_code text) returns table (developer_profile_id uuid, party_id uuid, display_name text, created_at timestamptz) language plpgsql security definer set search_path = '' as $$ begin perform private.require_urban_pipeline_authority(p_actor_user_id, p_organization_id, p_module, p_purpose_code); return query select profile.id, party.id, party.display_name, profile.created_at from public.urban_developer_profiles profile join public.party_records party on party.id = profile.party_id and party.organization_id = profile.organization_id where profile.organization_id = p_organization_id and profile.state = 'draft' and party.state = 'draft' and party.kind = 'legal_entity' order by profile.created_at desc, profile.id asc; end; $$;
create or replace function public.urban_link_draft_development_developer(p_actor_user_id uuid, p_organization_id uuid, p_module public.operating_module, p_purpose_code text, p_development_id uuid, p_developer_profile_id uuid, p_relationship public.urban_developer_relationship_kind, p_correlation_id uuid) returns uuid language plpgsql security definer set search_path = '' as $$ declare v_existing_target uuid; v_link_id uuid; begin perform private.require_urban_pipeline_authority(p_actor_user_id, p_organization_id, p_module, p_purpose_code); select target_id into v_existing_target from public.admin_audit_events where command_name = 'urban_link_draft_development_developer' and correlation_id = p_correlation_id and outcome = 'allowed' order by occurred_at desc limit 1; if v_existing_target is not null then return v_existing_target; end if; if not exists (select 1 from public.urban_developments where id = p_development_id and organization_id = p_organization_id and state = 'draft') or not exists (select 1 from public.urban_developer_profiles where id = p_developer_profile_id and organization_id = p_organization_id and state = 'draft') then raise exception using errcode = '42501', message = 'URBAN_DEVELOPER_LINK_CONTEXT_DENIED'; end if; insert into public.urban_development_developer_links (organization_id, development_id, developer_profile_id, relationship, state, created_by) values (p_organization_id, p_development_id, p_developer_profile_id, p_relationship, 'draft', p_actor_user_id) on conflict (organization_id, development_id, developer_profile_id) do update set updated_at = public.urban_development_developer_links.updated_at returning id into v_link_id; insert into public.admin_audit_events (correlation_id, actor_user_id, organization_id, command_name, outcome, target_type, target_id, payload_redacted) values (p_correlation_id, p_actor_user_id, p_organization_id, 'urban_link_draft_development_developer', 'allowed', 'urban_development_developer_link', v_link_id, jsonb_build_object('module', p_module::text, 'purpose_code', trim(p_purpose_code), 'relationship', p_relationship::text)); return v_link_id; end; $$;
create or replace function public.urban_list_draft_development_developers(p_actor_user_id uuid, p_organization_id uuid, p_module public.operating_module, p_purpose_code text) returns table (link_id uuid, development_id uuid, development_reference text, developer_profile_id uuid, display_name text, relationship public.urban_developer_relationship_kind, created_at timestamptz) language plpgsql security definer set search_path = '' as $$ begin perform private.require_urban_pipeline_authority(p_actor_user_id, p_organization_id, p_module, p_purpose_code); return query select link.id, development.id, development.internal_reference, profile.id, party.display_name, link.relationship, link.created_at from public.urban_development_developer_links link join public.urban_developments development on development.id = link.development_id and development.organization_id = link.organization_id join public.urban_developer_profiles profile on profile.id = link.developer_profile_id and profile.organization_id = link.organization_id join public.party_records party on party.id = profile.party_id and party.organization_id = profile.organization_id where link.organization_id = p_organization_id and link.state = 'draft' and development.state = 'draft' and profile.state = 'draft' and party.state = 'draft' order by link.created_at desc, link.id asc; end; $$;
revoke all on function public.urban_register_draft_developer(uuid, uuid, public.operating_module, text, uuid, uuid) from public, anon, authenticated; revoke all on function public.urban_list_draft_developers(uuid, uuid, public.operating_module, text) from public, anon, authenticated; revoke all on function public.urban_link_draft_development_developer(uuid, uuid, public.operating_module, text, uuid, uuid, public.urban_developer_relationship_kind, uuid) from public, anon, authenticated; revoke all on function public.urban_list_draft_development_developers(uuid, uuid, public.operating_module, text) from public, anon, authenticated; grant execute on function public.urban_register_draft_developer(uuid, uuid, public.operating_module, text, uuid, uuid) to service_role; grant execute on function public.urban_list_draft_developers(uuid, uuid, public.operating_module, text) to service_role; grant execute on function public.urban_link_draft_development_developer(uuid, uuid, public.operating_module, text, uuid, uuid, public.urban_developer_relationship_kind, uuid) to service_role; grant execute on function public.urban_list_draft_development_developers(uuid, uuid, public.operating_module, text) to service_role;
comment on table public.urban_developer_profiles is 'A108: perfil mínimo de construtora referenciado por Party jurídica em rascunho, sem cadastro fiscal, contato, documento, correspondente ou credencial.'; comment on table public.urban_development_developer_links is 'A108: associação estrutural de rascunho entre construtora e empreendimento, sem unidade, estoque, preço, anúncio, proposta, contrato ou financeiro.';
